// AlphaForgeAI News Pipeline — RSS Feed Sources
// Add or remove feeds here. Source names appear in the news cards.
return [
  { json: { url: 'https://feeds.feedburner.com/CoinDesk',                 source: 'CoinDesk'       } },
  { json: { url: 'https://cointelegraph.com/rss',                         source: 'Cointelegraph'  } },
  { json: { url: 'https://www.theblockcrypto.com/rss.xml',                source: 'The Block'      } },
  { json: { url: 'https://decrypt.co/feed',                               source: 'Decrypt'        } },
  { json: { url: 'https://bitcoinmagazine.com/.rss/full/',                source: 'Bitcoin Magazine' } },
  { json: { url: 'https://blog.coinbase.com/feed',                        source: 'Coinbase Blog'  } },
  { json: { url: 'https://www.binance.com/en/feed',                       source: 'Binance Blog'   } },
  { json: { url: 'https://blog.kraken.com/feed',                          source: 'Kraken Blog'    } },
];

// Feed order must match Define RSS Feeds node
const SOURCES = [
  'CoinDesk', 'Cointelegraph', 'The Block', 'Decrypt',
  'Bitcoin Magazine', 'Coinbase Blog', 'Binance Blog', 'Kraken Blog'
];

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenUrls) staticData.seenUrls = [];
const seenSet = new Set(staticData.seenUrls);

const allItems = $input.all();
const allArticles = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i];
  const source = SOURCES[i] || 'Unknown';
  if (item.json.error) { console.log(`Feed ${i} (${source}) failed: ${item.json.error}`); continue; }
  const xml = item.json.data || item.json.body || '';
  if (!xml || xml.length < 100) continue;
  allArticles.push(...parseRssItems(xml, source));
}

const seenThisRun = new Set();
const newArticles = [];
for (const article of allArticles) {
  const url = article.url.trim();
  if (!seenSet.has(url) && !seenThisRun.has(url)) {
    seenThisRun.add(url);
    newArticles.push({ ...article, url });
  }
}

// Persist (cap at 2000 to prevent unbounded growth)
const updated = [...staticData.seenUrls, ...Array.from(seenThisRun)];
staticData.seenUrls = updated.slice(-2000);

console.log(`Fetched ${allArticles.length} total. New (unseen): ${newArticles.length}`);
return [{ json: { articles: newArticles, count: newArticles.length } }];

// ── Helpers ──────────────────────────────────────────────────────────────────

function parseRssItems(xml, source) {
  const items = [];
  const re = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let m;
  while ((m = re.exec(xml)) !== null) {
    const body = m[1];
    const title = clean(tag(body, 'title'));
    let link = clean(tag(body, 'link'));
    if (!link) link = clean(tag(body, 'guid'));
    if (!title || !link || !link.startsWith('http')) continue;
    const rawDesc = clean(tag(body, 'content:encoded') || tag(body, 'description') || '');
    const description = rawDesc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 600);
    const pubRaw = clean(tag(body, 'pubDate') || tag(body, 'dc:date') || '');
    let published_at;
    try { published_at = new Date(pubRaw).toISOString().replace('.000Z', 'Z'); }
    catch { published_at = new Date().toISOString().replace('.000Z', 'Z'); }
    items.push({ title, url: link.trim(), description, published_at, source });
  }
  return items;
}

function tag(xml, t) {
  const m = xml.match(new RegExp('<' + t + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + t + '>', 'i'));
  return m ? m[1] : '';
}

function clean(s) {
  return s.replace(/<\!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').trim();
}

const { articles, count } = $json;

if (!articles || count === 0) {
  console.log('No new articles this run — skipping OpenAI analysis');
  return [];
}

// Cap batch size to control API cost (~$0.002 per run at 40 articles with gpt-4o-mini)
const batch = articles.slice(0, 40);

// Stash originals for enrichment after OpenAI response
const staticData = $getWorkflowStaticData('global');
staticData.pendingArticles = batch;

const lines = batch.map((a, i) =>
  `[${i + 1}] TITLE: ${a.title}\nSOURCE: ${a.source}\nURL: ${a.url}\nDESC: ${a.description}`
).join('\n\n');

const systemPrompt = `You are a professional crypto market intelligence analyst. Evaluate, summarize, and classify crypto news articles objectively.`;

const userPrompt = `Analyze the following crypto news articles. For each, return:\n- index: the number in brackets, e.g. 1\n- title: verbatim\n- url: verbatim\n- relevance_score: integer 1–10\n  8–10 = major market-moving (regulatory action, exchange issues, major protocol events, significant capital flows)\n  5–7  = relevant but not urgent\n  1–4  = low relevance, opinion, sponsored, or not crypto-specific\n- category: one of bitcoin | ethereum | defi | regulation | macro | exchange | nft | altcoins | security | mining | other\n- assets: array of crypto tickers mentioned, e.g. [\

const staticData = $getWorkflowStaticData('global');
const originals = staticData.pendingArticles || [];
const byUrl = {};
for (const a of originals) byUrl[a.url] = a;

const content = $json.choices?.[0]?.message?.content;
if (!content) { console.error('OpenAI returned no content'); return []; }

let parsed;
try { parsed = JSON.parse(content); }
catch (e) { console.error('JSON parse failed:', e.message, content.slice(0, 200)); return []; }

const scored = parsed.scored || [];
const qualified = scored.filter(s => (s.relevance_score || 0) >= 7);

console.log(`${qualified.length} of ${scored.length} articles scored >= 7`);

if (qualified.length === 0) return [];

const enriched = qualified.map(s => ({
  title:           s.title || '',
  url:             s.url || '',
  source:          byUrl[s.url]?.source       || 'Unknown',
  published_at:    byUrl[s.url]?.published_at || new Date().toISOString().replace('.000Z', 'Z'),
  category:        s.category    || 'other',
  assets:          Array.isArray(s.assets) ? s.assets : [],
  sentiment:       s.sentiment   || 'neutral',
  summary:         s.summary     || '',
  relevance_score: s.relevance_score,
}));

enriched.sort((a, b) => (b.relevance_score || 0) - (a.relevance_score || 0));

return [{ json: { qualified: enriched, count: enriched.length } }];

const { qualified, count } = $json;
if (!qualified || count === 0) return [];

const items = qualified.map(a => ({
  title:        a.title,
  source:       a.source,
  url:          a.url,
  published_at: a.published_at,
  summary:      a.summary,
  category:     a.category,
  assets:       a.assets,
  sentiment:    a.sentiment,
}));

const topStories = qualified.slice(0, 3);

return [{ json: {
  payload:     { schema_version: 1, items },
  topStories,
  count,
} }];

// Pull topStories from the payload node (passes through AFI ingest response)
// We stored topStories in static data as a fallback
const staticData = $getWorkflowStaticData('global');

// Re-read from the format-payload node output (should still be in previous item)
// n8n passes the INPUT item to continueOnFail downstream; topStories is there
const topStories = $json.topStories || staticData.topStoriesForX || [];
if (topStories.length > 0) staticData.topStoriesForX = topStories;

if (!topStories || topStories.length === 0) {
  console.log('No top stories — skipping X post');
  return [];
}

const storyLines = topStories.map((s, i) =>
  `${i + 1}. ${s.title} (${s.source})`
).join('\n');

const systemPrompt = `You write professional, calm, market-intelligence posts for AlphaForgeAI on X.com.`;

const userPrompt = `Write a single X post (tweet) summarizing today\'s top crypto market news.\n\nRULES:\n- Maximum 275 characters (strict)\n- Calm, professional, market-intelligence tone\n- No financial advice\n- No buy/sell recommendations\n- No price predictions\n- No hype (do not use words like \

)
- Mention the number of key stories or leading themes
- End the post with: alphaforgeai.io/news
- Max 1 relevant hashtag if it fits naturally

Today's top stories:
${storyLines}

Return ONLY the tweet text. No quotes, no explanation.`;

return [{ json: { systemPrompt, userPrompt } }];

const content = $json.choices?.[0]?.message?.content;
if (!content) { console.error('No tweet from OpenAI'); return []; }

// Strip surrounding quotes if OpenAI added them
let tweet = content.trim().replace(/^["']|["']$/g, '');

// Hard cap at 275 chars
if (tweet.length > 275) {
  tweet = tweet.slice(0, 272) + '...';
}

console.log(`Tweet (${tweet.length} chars): ${tweet}`);
return [{ json: { tweet } }];
